import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        // Grayness = (2 * rowOnes - m) + (2 * colOnes - n); the best row and best column intersect.
        int[] columns = new int[m];
        int best = 0;
        for (int r = 0; r < n; r++) {
            String row = next();
            int ones = 0;
            for (int j = 0; j < m; j++) {
                if (row.charAt(j) == '1') {
                    ones++;
                    columns[j]++;
                }
            }
            best = Math.max(best, ones);
        }
        int bestColumn = 0;
        for (int v : columns) bestColumn = Math.max(bestColumn, v);
        System.out.println(2 * (best + bestColumn) - n - m);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := int(nextInt()), int(nextInt())
	// Grayness = (2 * rowOnes - m) + (2 * colOnes - n); the best row and best column intersect.
	columns := make([]int, m)
	best := 0
	for r := 0; r < n; r++ {
		row := nextToken()
		ones := 0
		for j := 0; j < m; j++ {
			if row[j] == '1' {
				ones++
				columns[j]++
			}
		}
		best = max(best, ones)
	}
	fmt.Println(2*(best+slices.Max(columns)) - n - m)
}
